import GlobalStyle from './styles/GlobalStyle';
import ToDoList from './Components/ToDoList';
import RecoilStorageSync from './RecoilStorageSync';
import styled from 'styled-components';
import { useRecoilState } from 'recoil';
import { isDarkState } from './atoms/themeAtom';

const ThemeButton = styled.button`

`;

const MaterialIcon = ({className}) => (
  <i className={`material-icons ${props.className}`}>account_balance</i>
);

const Icon = styled(MaterialIcon)`
  background-color: green;
  font-size: 50px;
`;


function App() {
	const [isDark, setIsDark] = useRecoilState<boolean>(isDarkState);
	const onThemeToggleClick = () => {
		console.log(isDark)
		setIsDark((prev) => !prev)
	}

  return (
		<>
			<GlobalStyle/>
			<RecoilStorageSync/>
			<ToDoList/>
			<ThemeButton onClick={onThemeToggleClick}>
				{/* {isDark ? "dark" : "light"} */}

				<IconImg className="material-symbols-outlined">
					dark_mode
				</IconImg>
			</ThemeButton>
		</>
	);
}

export default App;
